import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type HoveringDataCardsProps = Record<string, any>;

const HoveringDataCards: React.FC<HoveringDataCardsProps> = ({
  backgroundColor = "#F3F4F6",
  cardBackgroundColor = "#FFFFFF",
  innerBackgroundColor = "#1E2532",
  textColor = "#111827",
  accentColor = "#4A90E2",
  cards = [
    { title: "Planning", emoji: "📝" },
    { title: "Designing", emoji: "🎨" },
    { title: "Building", emoji: "🏗️" },
    { title: "Testing", emoji: "🧪" },
    { title: "Shipping", emoji: "🚀" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scaling
  const s = Math.min(width, height) / 1080;

  return (
    <AbsoluteFill
      style={{
        backgroundColor,
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "row",
        gap: `${32 * s}px`,
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      {cards.map((card, index) => {
        // Staggered entrance animation
        const delay = index * 8;
        const entranceProgress = spring({
          frame: Math.max(0, frame - delay),
          fps,
          config: { damping: 14, mass: 1, stiffness: 80 },
        });

        // Continuous Hover Animation
        const hoverY = Math.sin((frame - delay) * 0.04) * 15 * s;

        // Combine animations
        const yOffset =
          interpolate(entranceProgress, [0, 1], [200 * s, 0]) + hoverY;
        const opacity = interpolate(entranceProgress, [0, 1], [0, 1]);

        // Dynamic shadow based on hover
        const shadowY = 20 * s + hoverY * 0.5;
        const shadowBlur = 40 * s + hoverY * 1;

        return (
          <div
            key={index}
            style={{
              width: 300 * s,
              height: 400 * s,
              backgroundColor: cardBackgroundColor,
              borderRadius: 16 * s,
              boxShadow: `0px ${shadowY}px ${shadowBlur}px rgba(0, 0, 0, 0.08)`,
              display: "flex",
              flexDirection: "column",
              padding: 24 * s,
              position: "relative",
              overflow: "hidden",
              opacity,
              transform: `translateY(${yOffset}px)`,
              transition: "none",
            }}
          >
            {/* Top Accent Bar */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                height: 6 * s,
                backgroundColor: accentColor,
                transition: "none",
              }}
            />

            {/* Inner Content Area */}
            <div
              style={{
                width: "100%",
                flex: 1,
                backgroundColor: innerBackgroundColor,
                borderRadius: 8 * s,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                marginBottom: 24 * s,
                position: "relative",
                transition: "none",
              }}
            >
              <div
                style={{
                  fontSize: 90 * s,
                  lineHeight: 1,
                  filter: "drop-shadow(0px 8px 16px rgba(0,0,0,0.2))",
                  transition: "none",
                }}
              >
                {card.emoji}
              </div>
            </div>

            {/* Title */}
            <span
              style={{
                fontSize: 22 * s,
                fontWeight: 700,
                color: textColor,
                textAlign: "left",
                letterSpacing: "-0.5px",
                transition: "none",
              }}
            >
              {card.title}
            </span>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default HoveringDataCards;